// The api the station profiles probe serves in place of src/api.ts (`scripts/browser-probe --desktop
// profiles`): the radio switch probe's three-radio station (radioswitch-api.ts), with three "My station"
// profiles in the snapshot, the third with a long name. `window.__probeProfiles(on)` hands the app a
// snapshot with or without them, so the probe can compare the bar both ways; `switchStationProfile`
// records each pick. Every other export of src/api.ts answers `[]`, generated by the probe.
import settingsFixture from '../src/components/__fixtures__/defaultSettings.json'

// Three profiles, the third with a long name: the picker must cap it, never widen the bar.
const PROFILES = [
  { id: 'home', name: '', call: 'KD9TAW' },
  { id: 'p1', name: 'Portable', call: 'KD9TAW/P' },
  { id: 'p2', name: 'Devil\'s Lake State Park, the north shore picnic area', call: 'KD9TAW/P' },
]
const base: any = (settingsFixture as any).radios[0]
const radio = (id: number, name: string, rigModelName: string, serialPort: string, bands: string[]) => ({
  ...base, id, name, rigModelName, serialPort, bands, enabled: true,
})
const settings: any = {
  ...settingsFixture,
  radios: [
    radio(0, 'FTdx10', 'Yaesu FTDX-10', 'COM3', []),
    radio(1, 'IC-9700', 'Icom IC-9700', 'COM5', ['2m', '70cm', '23cm']),
    radio(2, 'FT-991A', 'Yaesu FT-991A', 'COM7', ['2m', '70cm']),
  ],
  activeRadio: 0,
  routingRules: [
    { bands: ['2m', '70cm'], mode: 'fm', context: null, radio: 2 },
    { bands: ['2m', '70cm'], mode: 'digital', context: null, radio: 1 },
  ],
  defaultRadio: 0,
  radioSwitchPolicy: 'tell',
  stationProfiles: PROFILES.map((p) => ({ ...p, grid: 'EN52', state: 'WI', county: '', cqZone: null, ituZone: null,
    iota: '', park: '', powerW: 100, rig: '', antenna: '' })),
  activeStationProfile: 'home',
}
const summary = (id: number, name: string, band: string, dialMhz: number, bands: string[]) => ({
  id, name, band, dialMhz, sideband: 'USB', isActive: id === 0, catOk: id === 0 ? true : null, smeterDb: null, transmitting: false, bands,
})
let snapshot: any = {
  mycall: 'KD9TAW', mygrid: 'EN52', mode: 'Normal',
  radio: { dialMhz: 14.074, band: '20m', catOk: true, sideband: 'USB', transmitting: false, txEnabled: false, txAllowed: true,
    rxOffsetHz: 1500, txOffsetHz: 1500, txLevel: 0.5, slot: 0, operatingMode: 'DIGU' },
  radios: [summary(0, 'FTdx10', '20m', 14.074, []), summary(1, 'IC-9700', '2m', 144.174, ['2m', '70cm', '23cm']), summary(2, 'FT-991A', '2m', 146.52, ['2m', '70cm'])],
  activeRadioId: 0,
  radioPegged: false,
  stationProfiles: PROFILES,
  activeStationProfile: 'home',
  aiCw: { enabled: false, status: '', text: '' },
  link: { tier: 'FT8', periodSecs: 15, snrDb: -8, dtSec: 0.1, freqHz: 1500, rv: 0, state: 'idle', quality: 1 },
  stations: [], conversations: [], activePeer: null, qso: null, fieldDay: null, recentDecodes: [], harqRescues: 0,
}
let listener: ((s: any) => void) | null = null
const switched: string[] = []
;(window as any).__probeProfiles = (on: boolean) => {
  snapshot = on
    ? { ...snapshot, stationProfiles: PROFILES, activeStationProfile: 'home' }
    : { ...snapshot, stationProfiles: undefined, activeStationProfile: undefined }
  listener?.(snapshot)
  return on
}
;(window as any).__probeSwitched = () => switched
const selected: number[] = []
;(window as any).__probeSelected = () => selected

export function isTauri(): boolean { return false }
export function subscribeSnapshot(fn: (s: any) => void): () => void { listener = fn; return () => { listener = null } }
export async function getSnapshot(): Promise<any> { return snapshot }
export async function setActiveRadio(id: number): Promise<any> {
  selected.push(id)
  snapshot = { ...snapshot, activeRadioId: id, radios: snapshot.radios.map((r: any) => ({ ...r, isActive: r.id === id })) }
  return snapshot
}
export async function setOperatingMode(): Promise<any> { return snapshot }
export async function switchStationProfile(id: string): Promise<any> {
  switched.push(id)
  snapshot = { ...snapshot, activeStationProfile: id }
  return snapshot
}
export async function setArea(): Promise<any> { return snapshot }
export async function getSettings(): Promise<any> { return settings }
export async function routePreview(): Promise<any> { return { id: 1, name: 'IC-9700' } }
export async function clientStatus(): Promise<any> { return null }
export async function askLog(): Promise<any> { throw new Error('no log') }
export async function getAwards(): Promise<any> { return { achievements: [] } }
export async function getJourney(): Promise<any> { return { firsts: [], feats: [], ladders: [] } }
